//! Baked gradient-boosted decision layer over the explainable comparison
//! feature vector. Trained on the `train` split of `data/evaluation` with the
//! validation split for model selection by `tools/train_decision/gbm.py`;
//! the test split is only ever used by held-out verification. Regenerate with
//! `python3 tools/train_decision/render_gbm_rust.py` after retraining — do not
//! edit the ensemble by hand.
//!
//! The layer only reprices evidence already present on
//! [`ComparisonResult`]: every input
//! feature remains visible in `evidence`/`explanations`, so scored output
//! stays auditable end to end. Inference is a deterministic branch walk over
//! the baked trees: no allocation, no floating-point platform dependence
//! beyond ordered `f64` comparisons, and no external state.

use crate::core::types::ComparisonResult;

const INIT: f64 = -0.8867484292018544;
const LEARNING_RATE: f64 = 0.25;
/// Feature values extracted once per comparison, in the fixed baked
/// order the ensemble was trained with.
fn feature_vector(result: &ComparisonResult) -> [f64; 52] {
    let mut f = [0.0f64; 52];
    f[0] = result.swap_antonym.max(result.multi_swap_antonym) * result.character.unwrap_or(0.0);
    {
        let c = result.character.unwrap_or(0.0);
        f[1] = c * c;
    }
    f[2] = result.character.unwrap_or(0.0);
    f[3] = result.cognate_match;
    f[4] = result.cognate_match * result.character.unwrap_or(0.0).max(0.3);
    f[5] = result.character.unwrap_or(0.0) * result.lexicon_validity * result.single_word_pair;
    f[6] = result.confusable_swap;
    f[7] = result.substring_containment * result.character.unwrap_or(0.0).max(0.5);
    f[8] = result.contextual_semantic;
    f[9] = result.cross_language_semantic;
    f[10] = result.cross_script_agreement;
    f[11] = result.cross_script_pair;
    f[12] = result.decoded_similarity.unwrap_or(0.0);
    f[13] = result.entity_agreement;
    f[14] = result.entity_conflict;
    f[15] = result.exact_decode;
    f[16] = result.false_friend;
    f[17] = result.decoded_similarity.unwrap_or(0.0) * (1.0 - result.exact_decode);
    f[18] = result.lexical.unwrap_or(0.0);
    f[19] = result.lexicon_validity;
    f[20] = result.multi_swap_antonym;
    f[21] = result.multi_swap_synonym_coverage;
    f[22] = result.normalized_identity;
    f[23] = result.obfuscation_similarity.unwrap_or(0.0);
    f[24] = result.phonetic.unwrap_or(0.0);
    f[25] = if result.phonetic.is_some() { 1.0 } else { 0.0 };
    f[26] = result.semantic.unwrap_or(0.0);
    f[27] = if result.semantic.is_some() { 1.0 } else { 0.0 };
    {
        let s = result.semantic.unwrap_or(0.0);
        f[28] = s * s;
    }
    f[29] = result.semantic_without_lexical_overlap;
    f[30] = result.semantic.unwrap_or(0.0) * result.character.unwrap_or(0.0);
    f[31] = result.single_word_exact;
    f[32] = result.single_word_pair;
    f[33] = result.substring_containment;
    f[34] = result.swap_antonym;
    f[35] = result.swapped_word_similarity * result.swapped_phonetic;
    f[36] = result.swapped_word_similarity * result.lexicon_validity;
    f[37] = result.swap_synonym;
    f[38] = result.swapped_phonetic;
    f[39] = result.swapped_word_similarity;
    f[40] = result.symbolic.unwrap_or(0.0);
    f[41] = if result.symbolic.is_some() { 1.0 } else { 0.0 };
    f[42] = result.swap_synonym.max(result.multi_swap_synonym_coverage)
        * result.character.unwrap_or(0.0);
    f[43] = result.transliteration_compatibility;
    f[44] = result.transliteration_confidence.unwrap_or(0.0);
    f[45] = result.transliteration_semantic_agreement;
    f[46] = result.transliteration_semantic_conflict;
    f[47] = result.transliteration_similarity.unwrap_or(0.0);
    f[48] = result.transliteration_similarity.unwrap_or(0.0)
        * result.transliteration_confidence.unwrap_or(0.0);
    f[49] = result.character.unwrap_or(0.0)
        * (1.0 - result.lexicon_validity)
        * result.single_word_pair.max(0.5);
    f[50] = result.valid_swap_similarity;
    f[51] = result.visual.unwrap_or(0.0);
    for value in &mut f {
        if !value.is_finite() {
            *value = 0.0;
        }
    }
    f
}

struct Node {
    feature: i32,
    threshold: f64,
    left: i32,
    right: i32,
    value: f64,
}

